"""Reproduce reviewed curation for lessons 68-71; KB is opened mode=ro.

The four review passes were performed by the same GPT-6.1 Sol xhigh agent.
The program materializes those decisions and machine-checkable evidence anchors.
It never imports, updates a shared log, or writes outside its own lower outputs.
"""
import hashlib, json, sqlite3, sys
from collections import Counter, defaultdict
from pathlib import Path

sys.dont_write_bytecode = True
sys.stdout.reconfigure(encoding='utf-8')
BASE = Path(__file__).resolve().parent
KB = Path(r'C:\Users\13240\Desktop\RAG\shared-knowledge\v0.1.0')
PREFIX = 'volume_2-5332cd1b6038-'
NAME = 'c_stage_l068_l071_sol61'
REVIEWER = 'GPT-6.1 Sol xhigh / 阶段C下册68至71课四轮复核'
db = sqlite3.connect((KB/'graph.sqlite').as_uri()+'?mode=ro', uri=True)
db.row_factory = sqlite3.Row
db.execute('BEGIN')
metadata = {r['key']:json.loads(r['value']) for r in db.execute('SELECT * FROM metadata')}
P = {r['id']:dict(r) for r in db.execute("SELECT * FROM passages WHERE unit_id BETWEEN 'lesson-068' AND 'lesson-071' ORDER BY pdf_page,block_index")}
current = {r['id']:dict(r) for r in db.execute("SELECT * FROM claims WHERE review_status='reviewed'")}
all_existing_ids={r['id'] for r in db.execute('SELECT id FROM claims')}
registry = {r['label']:dict(r) for r in db.execute('SELECT * FROM concepts')}
candidate_by_passage=defaultdict(list)
for r in db.execute("SELECT cl.id,cl.review_status,e.passage_id FROM claims cl JOIN evidence e ON e.claim_id=cl.id JOIN passages p ON p.id=e.passage_id WHERE p.unit_id BETWEEN 'lesson-068' AND 'lesson-071' AND cl.review_status!='reviewed'"):
    candidate_by_passage[r['passage_id']].append(r['id'])
context_by_passage={}
section=''
for p in P.values():
    if ('(2007-' in p['text'] and p['role'] in ('author_body','author_commentary') and len(p['text'])<100):
        section=p['text']
    context_by_passage[p['id']]=section
claims = []
decisions = {}
pending = []

def add(lesson, slug, text, concepts, refs, level, reason, conditions=(), exceptions=(), note='', figures=()):
    cid = f'lower-l{lesson:03d}-c-stage-{slug}'
    assert cid not in all_existing_ids, cid
    assert cid not in {c['id'] for c in claims}, cid
    evidence=[]
    for ref in refs:
        short,quote = ref if isinstance(ref,tuple) else (ref,None)
        p = P[PREFIX+short]
        assert p['unit_id'] == f'lesson-{lesson:03d}'
        assert p['speaker']=='缠中说禅' and p['role'] in ('author_body','author_reply','author_commentary')
        quote = p['text'] if quote is None else quote
        start = p['text'].find(quote)
        assert start>=0 and p['text'][start:start+len(quote)]==quote, (cid,short,quote)
        evidence.append({'passage_id':p['id'],'quote':quote,'quote_start':start,'figure_ids':[PREFIX+f for f in figures]})
    contexts=list(dict.fromkeys(context_by_passage[e['passage_id']] for e in evidence))
    context = '第'+str(lesson)+'课；来源栏目：'+' / '.join(contexts)
    scope = '；'.join(conditions) or ('作者讨论的'+ '、'.join(concepts)+'对象；保留引文所在段明确前提')
    review_note = f'语境：{context}。适用条件：{scope}。四轮复核：完整读上下文、原子拆分、复用现有术语、逐条逆向核对引文。{note}'
    record = dict(id=cid,text=text,kind='explicit',conditions=list(conditions),exceptions=list(exceptions),concepts=list(concepts),ambiguity_status='none',review_note=review_note,importance_level=level,importance_reason=reason+'；等级为整理重要性判断。',reviewer=REVIEWER,evidence=evidence,relations=[])
    if figures:
        record['figure_review_note']='已实际查看 volume_2.pdf 实际PDF页 '+ '、'.join(str(int(f[1:5])) for f in figures)+' 的对应图，核对作者文字点号、走势方向与图示用途。配图origin_status仍为unverified；仅用于核对汇编内图文对应，不声称已经核实为原博客作者原图，也不由图补造文字未说的规则。'
    claims.append(record)
    return cid

def mark(short, category, reason, existing=()):
    assert PREFIX+short in P, short
    decisions[PREFIX+short]={'category':category,'reason':reason,'existing_claim_ids':list(existing)}

def hold(lesson,slug,shorts,issue):
    item={'id':f'lower-l{lesson:03d}-c-stage-pending-{slug}','lesson_number':lesson,'document_id':PREFIX[:-1],'passage_ids':[PREFIX+s for s in shorts],'status':'pending','issue':issue}
    pending.append(item)
    for s in shorts: mark(s,'valuable_pending',issue)

