add(68,'prediction-participates','作者从哲学角度把预测自身也视为分力，认为预测会介入被预测结果，并以观察者干预和测不准作类比。',['走势预测','市场分力'],['p0059-b010','p0060-b000'],3,'解释作者反对通常预测的论证层次',note='原文跨页续段；测不准是作者类比，不当作量子物理对金融的实证证明。')
