add(68,'classification-foundation','作者把所有预测的基础表述为分类，即把所有可能情况作完全分类。',['走势预测','完全分类'],['p0060-b002'],1,'确定本课方法的起点',note='保留作者对不可知事件预测准确性没有信心的语境。')
add(68,'no-prior-exclusion','在本课的预测分类方法中，作者反对预先排除分类，认为每次排除相当于再作一次预测，并主张确定各类的边界条件。',['完全分类','边界条件','走势预测'],['p0060-b003','p0060-b004'],2,'防止把分类变成提前猜定结果',note='原文提概率乘法原则；不补造相互独立性假设或概率公式。')
add(68,'piecewise-example','本课用分段函数f(X)=-1（X<0）、f(X)=0（X=0）、f(X)=1（X>0）说明每个函数值应对应明确的X范围。',['分段函数','边界条件'],['p0060-b005','p0060-b006'],3,'保存边界条件的公式示例',conditions=['本课用于说明分段边界的数学示例'],note='示例的负值区间不是股票价格定义；同段对走势按[0,∞)分类另作语境记录。')
add(68,'operations-piecewise','把走势划成有边界条件的情况后，还要预设每种情况对应的操作，再让市场在当下选择实际出现的情况。',['完全分类','分段函数','操作策略','当下'],[('p0060-b009','边界条件分段后，就要确定一旦发生哪种情况就如何操作，也就是把操作也同样给分段化了。然后，把所有情况交给市场本身，让市场自己去当下选择。')],1,'连接分类与实际执行')
