add(68,'case-no-new-high-triangle','在上述局部线段答疑中，作者说最终是否创新高问题不大；若不创新高，该段有可能形成三角形，未说必然形成。',['线段','三角形整理'],['p0071-b000'],3,'保留线段内非单边形态的可能性',conditions=['接续17—18局部走势答疑'],note='保留“有可能”，不推导三角形完整判据。')
add(68,'operations-at-least-one-minute','作者说明正常操作至少用1分钟以上级别；如果坚持在线段层次操作，则要用类背驰概念。',['操作级别','线段','类背驰'],['p0072-b001'],2,'保留推荐入口与明确允许的特殊操作',conditions=['以1分钟为最低走势级别的本课体系'],exceptions=['坚持线段操作时使用类背驰概念'],note='没有把“不用线段操作”绝对化为禁止，也没有把类背驰改成严格背驰。')

# Lesson 69: monthly example, completion, source scale, replies.
add(69,'monthly-same-method','分型、笔、线段的分辨原则在1分钟图与月线图上一样；月线图的低精度只看大概和大方向。',['周期K线图','分型','笔','线段','价格精度'],['p0072-b006'],2,'补充基本方法与观察精度的关系',note='与已复核62课任意周期原则一致，本课强调月线低精度的大方向用途。')
add(69,'monthly-invalid-fractals','本课月线图中的X表示分型不符合笔的规范：顶底之间没有至少一根K线，或不满足顶后接底、底后接顶。',['分型','笔','周期K线图'],['p0072-b007'],2,'保存图示筛选准则的联合条件',conditions=['本课上海指数月线图','用于选笔端点的分型'],figures=['p0073-fig1'],note='不把所有检测出的局部分型自动视为笔端点。')
add(69,'case-alternating-selection','在本课月线图首个红箭头与第二绿箭头的取舍中，作者以不能成一笔及不能连续两个底分型，确定只能取第二绿箭头；首个绿箭头随之不算笔中的顶。',['分型','笔'],['p0072-b008'],3,'保留按定义取舍的具体反例',conditions=['本课月线图所指首红箭头、第二绿箭头与第二红箭头'],figures=['p0073-fig1'])
add(69,'provisional-fractal-completion','当下尚未完成的图形中，暂定为笔端点的分型取舍可能随后续走势修改；已完成图形的取舍不能再修改，可修改说明图形尚未完成。',['完成','分型','笔','当下'],['p0072-b010','p0072-b011'],1,'保存暂定划分和完成的基础边界',conditions=['本课笔端点分型取舍与月线例子'],note='不将“分型取舍”泛化为任意已确认K线分型都可反复修改。')
add(69,'unfinished-boundaries','作者以走势必完美为依据，主张结合各级别图形未完成的性质，缩小理论上可能完成方式的边界，作为综合判断条件。',['走势终完美','完成','边界条件','级别'],['p0072-b011','p0073-b000'],2,'保存未完成状态用于条件分类的方法',note='“百分百纯理论保证”保留为作者的理论自述，不附带市场收益保证。')
add(69,'perfection-core','作者在第69课明确把走势必完美称为其理论核心，并提醒不能只按字面理解。',['走势终完美'],['p0073-b001'],1,'保存作者明示的理论中心')
add(69,'case-third-month-segment','在2007年8月的上海指数月线例子中，作者认为进行中的第3段连第一笔也未走完，而线段至少要三笔；即使该笔完成并经一笔调整后，仍至少应有一笔向上。',['线段','笔','完成'],['p0073-b002','p0073-b003'],3,'保存月线结构推演的阶段前提',conditions=['本课当时月线第3段','作者判定第一笔未完成'],figures=['p0073-fig1'],note='历史推演不改为对当前指数的预测。')
add(69,'case-month-class-third-buy','本课把2245至998点称为线段类中枢；如果调整那笔不跌破2245点，将构成线段的类第三类买点。',['类中枢','类买卖点','线段','第三类买点'],['p0073-b004'],3,'保存月线示例中类概念与价格条件',conditions=['2007年8月上海指数月线案例','调整笔不跌破2245点'],note='仍是“类”中枢/买点；不把线段类比提升为技术走势类型。')
add(69,'upward-stroke-top-needed','本课当前月线向上笔的完成必须构成顶分型，作者留下月线顶分型如何构成及相应策略的作业。',['笔','顶分型','完成','周期K线图'],['p0073-b005'],2,'保存方向与完成条件',conditions=['本课正在讨论的月线向上笔'],note='不是“所有方向的笔都需要顶分型”；作业完整答案仍待核。')
add(69,'case-no-third-buy-still-center','在2007年8月10日解盘中，作者因5分钟第三类买点未出现而仍把走势归为中枢震荡，未由当天顶住外围压力推定已经突破。',['第三类买点','中枢震荡'],['p0074-b003'],3,'保存案例的技术状态判定',conditions=['2007-08-10所讨论的5分钟中枢'])
add(69,'fund-fee-incentive','作者在2007年8月公募基金文章中比较管理费与收益提成：前者旱涝保收而激励弱于后者；后者牛市可能兴旺，而熊市在作者判断中则会引发法律经济纠纷。',['基金激励机制','宏观市场判断'],['p0075-b002'],4,'保留基金制度讨论的历史背景',conditions=['2007-08-13公募与私募发展模式讨论'],note='仅为作者当时判断，不是现行收费法律或投资建议；保留牛市“可能”和熊市“则会”的不同语气。')
add(69,'fund-public-scale-tradeoff','作者在当时经济法律社会结构的前提下，认为公募的合法公众募集规模优势以只收管理费为代价；以私募式收益提成改造公募分配不能解决可持续发展。',['基金激励机制','基金团队品牌'],['p0075-b003','p0076-b000'],4,'保存制度优势与分配方式的限定论述',conditions=['作者明示“至少在目前的经济、法律、社会结构下”','2007-08-13文章'],note='不当作今天公募或阳光私募允许收费范围的法律事实。')
add(69,'fund-star-turnover','作者认为高比例私募激励会使明星个人把公募当个人资源跳板，形成基金经理模式的恶性循环；双基金经理制在其判断中会扩大此问题。',['基金激励机制','基金团队品牌'],['p0076-b001'],4,'保存管理机制批评与因果主张',conditions=['2007-08-13作者对公募明星基金经理模式的判断'],note='“必然”等为作者语气，未作为实证已证因果。')
add(69,'fund-team-brand','作者提出公募应弱化个人明星、塑造有传统风格和综合研究力的团队品牌，并通过适当股权创新增加核心团队持股比例。',['基金团队品牌','基金激励机制'],['p0076-b002','p0076-b003'],3,'保存明确的团队治理方法建议',conditions=['公募可持续发展的作者方案','2007-08-13文章'])
add(69,'case-month-boundary','在当时月线中，作者把约4150点作为中线强弱边界，依据是上移后的1/2线、5月均线及7月长阳一半位置；有效站稳与失守对应不同走势条件。',['边界条件','均线','宏观市场判断'],['p0076-b004','p0077-b000'],4,'保存历史边界由多项条件组成的例子',conditions=['2007-08-13当时月线数值'],note='4150及4174等不作为持续有效常数；p76附图文字存在加注，未当独立作者证据。')
add(69,'case-exit-pullback-unfinished','2007年8月13日作者把1-14划为1分钟上涨、14-27为5分钟中枢、27-32为离开；离开和回抽尚未完成，第三类买点与其后背驰性走势决定是否扩为30分钟中枢。',['完成','走势分解','第三类买点','中枢扩展'],['p0077-b004'],3,'保存图示状态与后续条件',conditions=['2007-08-13从4200上来的图示走势'],figures=['p0077-fig1'],note='未将当时未完成的离开和回抽写成已确认第三类买点。')
add(69,'second-sequence-membership','在32—33划分争议中，作者指出后一向上段的特征序列看向下元素；已跌破原第一段底的那个向下元素不能算第二段特征序列成员。',['特征序列','线段'],['p0079-b011','p0080-b000'],2,'保留第二序列成员范围的反例',conditions=['2007-08-13的32—33争议','前段向下、拟议第二段向上'],note='只记录作者对该第二序列的成员排除，不把此句扩大为否认71课假设分型右侧辅助元素。')
add(69,'second-sequence-three-elements','第二种线段划分情形的第二特征序列若没有三个元素，就不可能出现所要求的分型和第二种分段。',['特征序列','线段破坏','分型'],['p0080-b001'],1,'保存第二种情况的元素数量前提',conditions=['第67课第二种线段划分情况','用于确认的第二特征序列'],note='与71课对第一序列分型的辅助预设分开；不混成所有分型元素最终都属原段的要求。')
add(69,'nine-segments-not-necessary','九段可延伸形成5分钟中枢，不等于所有5分钟中枢必须由九段构成。',['走势中枢','中枢延伸','线段'],['p0080-b005'],2,'保留充分可行结构与必要条件的区别',conditions=['以1分钟图线段为底层、讨论5分钟中枢'])
add(69,'case-third-buy-two-paths','在2007年8月14日5分钟第三类买点出现后，作者列出两种去向：继续上涨直至形成新5分钟中枢，或在目前附近形成大一级别30分钟中枢。',['第三类买点','中枢新生','中枢扩展'],['p0080-b006'],2,'保存当前级别下完整分支',conditions=['2007-08-14所讨论的5分钟第三类买点'],note='与68课一般性否定一致，此条固定该例的5分钟/30分钟对应。')
add(69,'case-33-unfinished-not-buy','作者否认33是该5分钟中枢的第三类买点，因为若取33，前面的1分钟离开走势未完成；其认可的离开27-32与回抽32-35都是标准1分钟走势类型。',['第三类买点','次级别','完成'],['p0081-b008'],2,'保留买点中次级别走势完成要求的反例',conditions=['2007-08-14中枢14-27与点33/35的案例'],figures=['p0080-fig1'])
add(69,'chart-precision-not-operation-level','只看5分钟图也仍须分笔和线段；用1分钟图只是观察更精细，不决定操作级别。笔和线段是任何图表精度下必要的结构。',['周期K线图','价格精度','操作级别','笔','线段'],['p0081-b011'],2,'区分观察工具精度与被观察走势级别',note='复用现有周期K线图/操作级别术语，不把5分钟K线图等同5分钟操作。')
add(69,'center-overlap-key','在14—27是否构成5分钟中枢的答疑中，作者指出关键是重合部分，而非某高点是否足够高。',['走势中枢','重叠'],['p0082-b011'],3,'保存定义判断中相关与不相关条件的例子',conditions=['2007-08-14中枢14—27争议'])
add(69,'three-sublevel-overlap','5分钟中枢只须三个1分钟走势类型有重合，不要求内部所有线段都重合；全部线段重合并延伸九段是特殊情况，也可视为三个1分钟走势类型重合。',['走势中枢','次级别','重叠','中枢延伸'],['p0082-b014'],1,'澄清中枢递归定义与九段特殊情形',conditions=['以1分钟图线段为底层讨论5分钟中枢'],note='保留“走势类型”而非“三笔”或任意三条线段。')
add(69,'case-daily-comparison-same-level','在2007年8月14日晚日线背驰段答疑中，作者要求比较同级别中枢之间的段，选择去年8月至今年5月29日；春节前后中枢级别不同，不能替代该比较对象。',['背驰段','同级别','走势中枢'],['p0083-b002'],3,'保存同级别比较的具体教学案例',conditions=['2007-08-14当时日线背驰段问题'],figures=['p0083-fig1'],note='“三笔/一笔”是此日线图的观察线索，未推广为所有日中枢定义。')
add(69,'case-pressure-two-thirds','作者在当时4174点1/2线突破后的答疑中把下一压力定为2/3线，并给出5089=1429+183(月)×30×2/3的示例计算。',['经验压力线','边界条件'],['p0083-b004'],4,'保留有数值公式的历史例子',conditions=['2007-08-14当时压力线问题'],note='原式按引文保留，未推广为普适股价预测公式。')
add(69,'higher-chart-macd-assistance','在2007年8月15日17—38的1分钟上涨背驰案例中，作者说可在5分钟图上比较对应1分钟走势的力度，因MACD辅助判断更明显。',['MACD','背驰','周期K线图'],['p0083-b009','p0084-b000'],3,'保存观察精度切换下比较对象不变的用途',conditions=['2007-08-15该1分钟上涨案例','5分钟图对照同一1分钟走势区间'],note='不推导必须永远使用大一级K线MACD。')
add(69,'no-chasing-growth-patience','作者在中小板成长股附文中要求关注成长性并有耐心，同时明确任何股票都不值得追高，包括该案例的002149。',['追高','操作策略','成长性'],['p0084-b002','p0084-b003'],3,'保存成长性关注与不追高的联合提醒',conditions=['2007-08-15中小板成长股讨论'],note='未将具体个股成长叙述当成独立核实的基本面事实。')

# Lesson 70: associativity, scale-dependent actions, endpoint caveat and Q&A.
add(70,'associativity-connects','作者把结合律称为连接走势之间关系最重要的规则，并据此选择更有利于观察的走势分解。',['结合律','走势分解'],['p0085-b002','p0085-b004'],1,'保存分解变换的核心规则')
add(70,'associativity-invariance-claim','作者宣称其理论在保持结合律的走势分解变换下分析原则不变，并称可严格证明其唯一性。',['结合律','分解多样性','走势分解'],['p0085-b003'],3,'如实保留作者的理论宣称及本课证据边界',note='记录“作者宣称”；本课未给出该唯一性证明，整理者不声称已完成数学证明。')
add(70,'five-center-three-paths','形成本例5分钟中枢后，作者列三类后续：向上第三类买点并经1分钟向上走势形成新5分钟中枢；向下第三类卖点并经1分钟向下走势形成新5分钟中枢；中枢延伸，或第三类买卖点后扩展成30分钟中枢。',['走势中枢','第三类买卖点','中枢新生','中枢延伸','中枢扩展'],['p0085-b005','p0085-b006','p0085-b007','p0085-b008'],1,'保存完整三分分类及各级别条件',conditions=['本例已形成8—17的5分钟中枢'],note='三类合在同一命题，避免把每个有前提分支写成必然无条件后果。')
add(70,'case-observe-selected-path','作者认为无需预猜上述分类，走势当下自己选择；本例17—38构成1分钟上涨，32—35的最后1分钟中枢正扩出新5分钟中枢雏形，所以属于第一分支。',['当下','完全分类','完成','中枢扩展'],['p0086-b000'],3,'保存观察事实与雏形未完成之别',conditions=['2007-08-15当时8—17及17—38案例'],figures=['p0085-fig1'])
add(70,'case-new-center-unfinished-choice','本例新的5分钟中枢至少应完成，但是否进一步扩为30分钟或出现第三类买点再上涨，应与8—17中枢同样按分类处理，无须预猜。',['完成','走势中枢','中枢扩展','第三类买点'],['p0086-b001'],2,'保存完成义务与未选定路径',conditions=['2007-08-15本例新的5分钟中枢雏形'])
add(70,'case-thirty-minute-no-action','在本例中，按30分钟级别操作者对5分钟中枢移动和震荡只需看明白，无须进行操作。',['操作级别','中枢震荡','操作策略'],[('p0086-b002','如果是按30分钟操作的，这些5分钟的中枢移动、震荡之类的活动根本无须理睬，只要看明白就是，根本无须操作')],2,'保存大操作级别与小波动的关系',conditions=['本例按30分钟级别操作','所述5分钟中枢移动、震荡'])
add(70,'case-five-minute-divergence-exit','本例按5分钟级别操作且不参与大于5分钟级别震荡者，应等5分钟上涨出现背驰后退出。',['操作级别','背驰','操作策略'],[('p0086-b002','如果是按5分钟级别操作，那么就是不参与大于5分钟级别的震荡，那么就等5分钟上涨出现背驰后走人')],2,'保存操作级别对应的退出条件',conditions=['本例按5分钟级别操作','不参与大于5分钟级别的震荡'])
add(70,'case-one-minute-recall','本例按1分钟级别操作时，作者主张当早因1分钟上涨背驰先退出；其后必回抽最后1分钟中枢并至少形成新5分钟中枢，再按5分钟震荡走势回补。',['操作级别','背驰','中枢震荡','走势中枢'],[('p0086-b002','如果是按1分钟级别操作，那么今天早上就该先走，为什么？因为1分钟的上涨出现背驰，按照本ID的理论，后面必然回抽到最后一个1分钟的中枢之内，从而至少形成一个新的5分钟中枢。然后根据5分钟震荡的走势进行回补就可以。')],2,'保存1分钟策略的触发和回补依据',conditions=['2007-08-15按1分钟操作的该上涨案例','1分钟上涨背驰成立'])
add(70,'temporary-center-decomposition','按多样性分解原则，本例新5分钟中枢可暂从最后1分钟中枢起算，先据此操作，待走势自然选择后再作更合理划分；暂时划分不改变该级别的操作原则。',['分解多样性','走势中枢','当下','操作策略'],['p0086-b003'],2,'保存暂定分解的作用与更新顺序',conditions=['本例正在形成的新5分钟中枢'],note='不是任意改写已完成线段；对象是走势中枢的多样性分解。')
add(70,'case-macd-compare-correspondence','本例背驰比较对象是27—32与35—38；为免在1分钟图相加MACD过于麻烦，可用5分钟图的对应两段辅助比较，红箭头回抽对应最后1分钟中枢形成。',['MACD','背驰','走势分解'],['p0086-b004'],2,'保存跨图精度比较时相同走势区间的对应',conditions=['2007-08-15该背驰案例','比较同一走势的27—32与35—38'],figures=['p0087-fig1'])
add(70,'segment-end-not-extreme','本例1分钟图38处线段标记不是最高点；作者说明线段结束位置并非规定必须最高或最低，关键是至少三笔，37至最高点不足三笔不能据此认为线段已完成。',['线段','笔','完成','高低点'],[('p0087-b000','1分钟图上38标记的位置用红箭头给出，显然，那不是最高的位置。为什么？没有人规定分段的结束位置一定是最高、最低的，关键要有至少三笔，因为从37开始到最高的位置，没有三笔，所以不能认为线段已经完成。')],1,'保存线段图示端点与完成标准的限定',conditions=['本例37—38线段及最高点关系'],figures=['p0087-fig2'],note='保留本例，不另造所有线段端点算法。')
add(70,'type-full-fluctuation-region','作者在解释本例37—38时说明，线段用于图形规范化；在1分钟级别看该段，结束在最高位置，如在5分钟中枢看1分钟走势类型重叠应计整个走势类型波动区域。',['线段','走势类型','价格区间','重叠'],[('p0087-b000','但在1分钟级别上看，那么37-38这一段，就结束在最高的位置，为什么？线段的存在，是为了让图形规范化，就如同在5分钟中枢里，看1分钟走势类型的重叠，是把整个走势类型的波动区域算在一起看，道理是一样的。')],2,'区分图形规范标点与走势类型完整波动区域',conditions=['本例1分钟级别37—38与5分钟中枢重叠的类比'],figures=['p0087-fig2'],note='不把“在1分钟级别上看”抹成与前一句同一层次端点自相矛盾。')
add(70,'case-4700-level-boundary','作者在2007年8月16日以图中16、约4700点划分短线调整级别：跌破则只剩30分钟中枢震荡；未破则仍可能形成新5分钟震荡、维持原5分钟上涨。',['边界条件','中枢震荡','级别'],['p0088-b005','p0089-b000'],3,'保存历史边界的方向与两支状态',conditions=['2007-08-16图中16与4700点案例'],figures=['p0088-fig1'])
add(70,'case-46-provisional','2007年8月16日图中46只是大致标记，并非百分百确定；如果次日大幅高开，就要改变。',['当下','完成','线段'],['p0089-b003'],3,'保存收盘暂定点的可修改性',conditions=['2007-08-16图中46及次日高开假设'],figures=['p0088-fig1'])
add(70,'three-strokes-not-center','对32—35的1分钟中枢，作者明确指出32—33、33—34、34—35是线段而不是笔，反对以三笔构成该1分钟中枢。',['最小级别中枢','笔','线段'],['p0089-b009'],1,'澄清最低级别中枢的底层对象',conditions=['本例1分钟图上的32—35中枢'],note='读者对三笔构成同级中枢的前提未被作者接受。')
add(70,'macd-retracement-not-divergence','MACD只是辅助，先要找到中枢与正确比较走势；MACD回抽本身不等于存在背驰。',['MACD','背驰','走势中枢'],['p0089-b010'],1,'保存背驰与辅助指标的必要区分')
add(70,'stroke-endpoints-vs-inner-shapes','一笔只有一顶一底；笔端点若出现顶接顶，其中一个不是真正端点。笔自身只有两个端点，线段内部各笔则可形成各种形态，只要未破坏线段。',['笔','分型','线段','线段破坏'],['p0089-b011'],1,'防止笔的端点规则与线段内部形态混用',note='本段“笔就是一线段”按普通几何连线理解，未归一为技术“线段”与笔同义。')
add(70,'third-buy-has-level','第三类买点有级别，1分钟第三类买点不能保证永远上涨；其后可继续上涨或形成更大级别，区分要看相应走势有无盘整顶背驰。',['第三类买点','级别','盘整背驰','中枢扩展'],['p0090-b001'],1,'保存买点后果的级别与完整分支',note='作者未确认读者所问联通买点确实存在；不记录该前提为事实。')
add(70,'third-buy-up-process-only','即使第三类买点后走向更大级别情形，从该买点到盘整顶背驰仍理论保证一段向上过程，但向上后并不保证不再向下。',['第三类买点','盘整背驰','中枢扩展'],['p0090-b002'],2,'保存局部方向保证与后续不保证的范围',conditions=['第三类买点确实成立','其后形成更大级别的分支'])
add(70,'gap-fractal-if-definition','在读者询问缺口能否作顶底分型组成部分的语境中，作者回答可以，关键是符合定义。',['缺口','分型'],['p0090-b005'],3,'保存肯定答复及定义条件',conditions=['紧邻读者关于缺口可否作分型组成部分的问题','符合分型定义'],note='不把“当然可以”理解为无条件把每个缺口都当K线或补造包含算法。')
add(70,'long-term-large-level','作者将长期投资定义为在年、季、月线等大级别买点介入、持有至大级别卖点卖出，并反对用长期投资掩盖原本小级别的操作失误。',['长期投资','操作级别','买卖点'],['p0090-b008',('p0090-b009','关键操作上要有正确的思维方法，任何一个操作，必须要知道对在哪里、错在哪里。如果本来想1分钟操作的，结果搞错了，就用长期投资搪塞，这样是很难进步的。'),'p0092-b007'],2,'保存长期策略的买卖点级别与错误归因',note='不把个股最终解套的历史预测一并泛化。')
add(70,'selling-psychology-practice','针对能抓底却错过顶背驰的提问，作者归因为贪婪心态，主张宁愿卖早不要卖晚；卖点精度需在实际操作中磨练。',['操作熟练程度','市场心理','卖点','交易成本'],['p0090-b014'],3,'保存适用于该提问的心理与训练建议',conditions=['作者针对该读者底背驰较准、顶背驰错过的问题'],note='“心态问题”是对该提问的答复，不作所有卖点识别错误的唯一原因。')
add(70,'auction-minute-counts','本例36—37的笔划分必须计入9:25竞价的一分钟；作者称竞价是重要时刻，且本例该处形成下方中枢第三类买点。',['集合竞价','周期K线图','笔','第三类买点'],['p0091-b002','p0091-b004'],2,'保存竞价数据参与划分的明确答复',conditions=['2007-08-16对36—37划分的答疑'],figures=['p0091-fig1'])
add(70,'case-exclude-auction-alternative','作者为说明数据口径差异给出反事实：若坚持不算9:25竞价，则本例不成该笔，应把36标到4915最高点；作者随后明确真实口径必须计入竞价。',['数据源一致性','笔','线段'],['p0091-b003','p0091-b004'],3,'保留反事实示例与作者真实主张之别',conditions=['本例假设排除9:25竞价的反事实'],note='不将反事实替代标记作为作者推荐口径。')
add(70,'case-one-first-fill','对当日44处的答疑，作者判为第一种情况，即特征序列缺口被第一笔封闭，因此无需研究第二特征序列分型。',['特征序列缺口','线段破坏','特征序列'],['p0091-b007'],2,'保存第一种和第二种判断对象的区别',conditions=['2007-08-16作者对图中44处的第一种情况判定'],note='此处第一种“缺口被第一笔封闭”与67课标准序列两元素无缺口措辞相衔接；不自行补特殊A算法。')
add(70,'feature-opposite-and-normalize','作者确认应先处理包含关系、转为标准特征序列再看分型，同时强调特征序列元素方向与实际线段走势相反。',['特征序列','标准特征序列','包含处理','分型'],['p0091-b010'],2,'保存对读者操作顺序的确认及方向提醒',conditions=['紧邻读者p0091-b009提出的先包含处理再看分型'],note='回复本身以“当然没错”确认该问题；顺序引用保留读者为上下文，不用读者句作直接证据。')
add(70,'case-one-three-strokes','在当日44处已判第一种、无特征序列缺口的语境中，作者说这种情况下任何三笔都构成对前线段的破坏。',['线段破坏','笔','特征序列缺口'],['p0092-b001'],2,'保存三笔陈述成立的具体情况',conditions=['作者已判本例为第一种情况','不存在特征序列缺口'],note='不扩为任意位置的任意三笔，也不删去71课第一笔先破坏等限定。')
add(70,'case-two-not-any-three','第二种线段划分情况中，并非任何三笔都能构成破坏，即使最终封闭特征序列元素间缺口；若被第一个就封闭，则已变成第一种情况。',['线段破坏','特征序列缺口','笔'],['p0092-b002'],1,'保存不能仅凭最终补缺口判断的例外',conditions=['按第二种情况判断线段破坏'],note='与第67课第二序列有分型、不强制补缺口并列保留。')

# Lesson 71: exact definitions and author replies; no program-rule imports.
add(71,'same-sequence-inclusion','讨论特征序列元素的包含关系，首先须是同一特征序列的元素；不同特征序列间讨论包含关系没有意义，向上段与后接向下段的元素方向也相反。',['特征序列','包含关系','线段'],['p0092-b010','p0093-b001'],1,'保存第71课包含关系的首要对象限制')
add(71,'before-stroke-break','前线段未被笔破坏时，还不能定义后特征序列元素；判断仍在同一前特征序列进行，因此可以定义其分型并处理包含关系。',['特征序列','笔破坏','包含关系','分型'],[('p0092-b011','因为在实际判断中，在前一段没有被笔破坏时，依然不能定义后特征序列的元素，这时候，当然可以存在前一特征序列的分型，这时候，由于还在同一特征序列中，因此，序列元素的包含关系是可以成立的')],1,'保存实际判断时归属与破坏状态的时序',conditions=['前线段尚未被笔破坏'])
add(71,'later-first-break-no-inclusion','若最早破坏前线段的一笔不是转折点后的第一笔，转折前最后特征元素与转折后第一特征元素之间必有缺口，后者与最早破坏笔不包含，否则缺口不能封闭、该笔也不能破坏前段。',['笔破坏','特征序列缺口','包含关系'],[('p0092-b011','而当前一段被笔破坏时，显然，最早破坏的一笔如果不是转折点开始的第一笔，那么，特征序列的分型结构也能成立，因为在这种情况下，转折点前的最后一个特征序列元素与转折点后第一个特征元素之间肯定有缺口，而且后者与最早破坏那笔肯定不是包含关系，否则该缺口就不可能被封闭，破坏那笔也就不可能破坏前一线段的走势。')],1,'保存较复杂分支的完整联合条件',conditions=['前线段已被笔破坏','最早破坏笔并非转折点后的第一笔'],note='不把必要条件倒置成“补缺口即线段破坏”。')
add(71,'stroke-break-needs-gap-fill','线段被笔破坏须封闭其最后一个特征序列缺口；这只是笔破坏条件，不能因此推定线段已被新线段破坏。',['笔破坏','特征序列缺口','线段破坏'],[('p0092-b011','线段要被笔破坏，那么必须其最后一个特征序列的缺口被封闭，否则就不存在被笔破坏的情况。'),'p0101-b008'],1,'保存必要条件与非充分性的对应',conditions=['讨论线段的笔破坏'],note='联合作者同课答疑消除与67课第二种不补缺口的表面矛盾。')
add(71,'first-break-intermediate','如果从转折点开始的第一笔就是最早破坏笔，并随后延伸成新线段，该笔处于待定中间地带，不能严格归为前段或后段的特征序列；即便似有包含关系也不能算。',['笔破坏','特征序列','包含关系','完成'],['p0092-b012','p0093-b000'],1,'保存特殊首笔的归属与待定状态',conditions=['最早破坏笔为转折点后的第一笔','该笔后续延伸成为线段的走势'],note='不定义程序中的特殊A选取、更早回溯或EPS。')
add(71,'first-break-third-passes-end','从转折点开始，第一笔先破坏前线段，再延伸成三笔，且第三笔突破第一笔结束位置时，新线段一定形成、前线段一定结束。',['笔破坏','线段破坏','笔','完成'],['p0093-b002'],1,'保存第一种核心确认的联合充分条件',conditions=['从假设转折点开始','第一笔已破坏前线段','延伸出三笔','第三笔突破第一笔结束位置'],note='原文“破点”按相邻段“先破第一笔结束位置”读作突破，未修改原始文本或引文。')
add(71,'third-inside-indeterminate','在上述首笔已破坏前段的情形中，第三笔完全在第一笔范围内时，三笔暂不能分辨向上或向下，也不能据此定义特征序列方向。',['笔破坏','特征序列','完成'],[('p0093-b003','这种情况还有更复杂一点的情况，就是第三笔完全在第一笔的范围内，这样，这三笔就分不出是向上还是向下，这样也就定义不了什么特征序列，为什么？因为特征序列是和走势相反的，而走势连方向都没有，那怎么知道哪个元素属于特征序列？')],1,'保存三笔完全包含时的待定状态',conditions=['承接第一笔已破坏前线段的语境','第三笔完全在第一笔范围内'])
add(71,'third-inside-resolution','上述第三笔在第一笔内的待定结构有两种最终结果：先突破第一笔结束位置则新线段成立、旧线段破坏；先突破第一笔开始位置则旧段仅被一笔破坏后沿原方向延续，新线段不出现。',['笔破坏','线段破坏','走势延伸','完成'],[('p0093-b003','这种情况，无非两种最后的结果：1、最终还是先破了第一笔的结束位置，这时候，新的线段显然成立，旧线段还是被破坏了；2、最终，先破第一笔的开始位置，这样，旧线段只被一笔破坏，接着就延续原来的方向，那么，显然旧线段依然延续，新线段没有出现。')],1,'保存待定结构完整两支及先后条件',conditions=['第一笔破坏前段','第三笔完全在第一笔内的待定结构'],note='不由此补造先后同时触及、相等或价格EPS的处理规则。')
add(71,'fractal-hypothetical-members','线段两种情况的分型元素是在假设旧线段未破坏的角度下使用；若最终线段破坏，分型右侧元素可不属于前后任一段的严格特征序列，不能把分型辅助预设与同段包含对象要求混同。',['特征序列','分型','包含关系','线段破坏'],['p0093-b004','p0093-b005'],1,'保存判定时预设与最终成员归属的区别',conditions=['用于判定旧线段是否结束的分型结构','旧线段后来最终被破坏'],note='此条限定第一序列判定辅助结构，未取消69课对第二序列三元素的要求。')
add(71,'boundary-hypothesis-procedure','当下划分线段可先假设某转折点为两线段分界，再按两种情况检验；满足任一种则是真分界，否则不是、原线段延续。',['线段','线段破坏','当下'],['p0093-b006'],1,'保存可执行的判断程序',conditions=['按第67课精确定义的两种情况逐项检查'])
add(71,'first-element-immediately-before','特征序列分型的第一元素，是假设转折点前线段的最后一个特征元素；第二元素是转折点开始的第一笔。二者同向，有缺口归第二种，无缺口归第一种，再按定义检验。',['特征序列','特征序列缺口','分型','线段'],['p0093-b007','p0094-b000'],1,'保存第一元素身份及两种情况的分界',note='不把“最后一个”改写为历史最高A、最低L或最高次高回溯算法。')
add(71,'hypothetical-cross-boundary-no-inclusion','假设转折点前后这两个元素因已假设为不同性质、不一定属于同一特征序列，不能在二者间应用包含关系。',['特征序列','包含关系'],[('p0094-b001','在这假设的转折点前后那两元素，是不存在包含关系的，因为，这两者已经被假设不是同一性质的东西，不一定是同一特征序列的')],1,'保存假设边界两侧包含处理的排除范围',conditions=['第71课假设转折点前最后特征元素与转折后第一笔'])
add(71,'after-boundary-inclusion-allowed','假设转折点后用于顶分型的元素可以应用包含关系，因为它们或者同为旧线段延续中的特征序列，或者同为新线段的非特征序列，具有同一性质。',['特征序列','包含关系','顶分型'],[('p0094-b001','但假设的转折点后的顶分型的元素，是可以应用包含关系的。为什么？因此，这些元素间，肯定是同一性质的东西，或者就是原线段的延续，那么就同是原线段的特征序列中，或者就是新线段的非特征序列中，反正都是同一类的东西，同一类的东西，当然可以考察包含关系。')],1,'保存转折后同性质元素允许处理的理由',conditions=['假设转折点后的顶分型元素'],note='仅按原文顶分型论述记录；不自动生成向下镜像算法。')
add(71,'diagram-correction-notice','第71课明确提示上图最后一个有问题，应看第81课更正说明。',['线段','特征序列'],[('p0094-b002','注意，上图最后一个有问题，请看课程81里的更正说明。')],2,'保存作者对本课示例的明确更正标记',conditions=['本课上方四图的最后一图'],figures=['p0094-fig2'],note='已看黑色四图，最后图不能作为无条件正确例证；未核第81课更正全文，正确替代图仍pending；p94/95陈仁2008后加图不作作者证据。')
add(71,'case-two-lines-confirmed','作者在本课明确判断大盘网友所问图依定义是两线段，并确认当日42—44分段成立；该判断与同段对最后一个示意图的更正提醒分别保留。',['线段','线段破坏'],[('p0094-b002','大盘网友问到的那个图，显然，根据定义，是两个线段，而今天42-44的分段，显然也是成立的。')],3,'保存明确例图答复且不抹去更正边界',conditions=['作者所指大盘网友图及2007-08-16的42—44案例'],note='本条仅复述文字确认，不自行将未明确对应的图指认成具体标准组合图。')
add(71,'case-gdp-dynamic-analogy','作者在2007年8月20日以GDP作总市值波动中枢的宏观类比，强调GDP会变、估值中枢可上移；结构性泡沫仍可上涨，但中短期理由不足以抗拒回拉压力时将调整。',['宏观估值中枢','宏观市场判断','成长性'],['p0097-b001','p0097-b002'],4,'保存宏观类比的动态条件',conditions=['2007-08-20总市值超GDP的历史论述'],note='不与技术走势中枢共用严格定义，不将30%或300%示例当固定阈值。')
add(71,'case-growth-resists-bubble','在该泡沫化框架中，作者认为长期抗拒泡沫依靠成长性推动估值中枢上移；成长不足以支持时会破裂，且中短期跌破中枢形成低估可成为中长期机会。',['宏观估值中枢','成长性','宏观市场判断'],['p0097-b004','p0097-b005'],4,'保存宏观背景中的条件性方法论',conditions=['作者当时中国市场泡沫化框架','成长性是否支持中枢上移'],note='属于作者宏观判断，不是收益保证或现行估值定理。')
add(71,'case-strategic-hold-to-sell','作者在当时泡沫化状态下主张不再战略性买进、保持战略性持有，等待第一阶段长线卖点出现；这是其当时行情定性对应的策略。',['长期投资','买卖点','操作策略'],['p0097-b007'],4,'保存具体历史策略的触发背景',conditions=['2007-08-20作者判为第一阶段成分股泡沫化生存状态'],note='不推广成任何泡沫都应无条件满仓持有。')
add(71,'case-multiple-interpretations','2007年8月20日作者说8—49可看作30分钟中枢，也可按8—17的5分钟中枢及17—38回拉解释；超短线先看32—41的5分钟中枢震荡，须第三类买点才算向上突破。',['分解多样性','中枢震荡','第三类买点','走势中枢'],['p0098-b002'],3,'保存多样性分解和突破确认的例子',conditions=['2007-08-20所指上海指数点8—49的案例'],figures=['p0098-fig1'],note='248点大涨并不被作者直接当成已有效突破。')
add(71,'case-breakout-confirm-levels','在2007年8月21日解盘中，作者要求先形成5分钟第三类买点、再形成30分钟第三类买点，才能最终确认所讨论突破有效；此前仍视为中枢震荡。',['第三类买点','确认','中枢震荡','级别'],['p0100-b004'],3,'保存不同级别确认的顺序',conditions=['2007-08-21本次突破案例'],note='不改写为所有突破永远必须恰好5分钟再30分钟。')
add(71,'case-pressure-experience-not-prior','作者把当时1/2线后2/3线、再3/4线说成带较大经验值的预测模板，并以问题提出，目的是避免先入为主影响当下判断。',['经验压力线','当下','走势预测'],['p0100-b005','p0100-b006'],3,'保存经验外推与当下判定的不同身份',conditions=['2007-08-21所述5089点及比例压力线'],note='不把此模板提升为与分型中枢同等严格定义。')
add(71,'connection-two-sublevel','对中枢破坏定理的连接疑问，作者说与连接的结合性有关，只要能分解出两段次级别走势即可；更详细的不同分解留待后课。',['结合律','次级别','走势分解','中枢破坏'],['p0100-b012'],2,'保存答复的已说范围与尚未展开边界',conditions=['紧邻读者关于第18课两个次级走势连接的疑问'],note='读者引述的定理全文未自动转录为作者本课新增证据。')
add(71,'type-level-from-center','不能仅由“盘整”或“趋势”名称判定哪个级别更高；关键是中枢及其级别，没有中枢和中枢级别就无从谈盘整、趋势及其级别。',['盘整','趋势','走势中枢','级别'],['p0100-b013'],1,'保存走势类型级别归属的判断依据')
add(71,'consolidation-end-third-point','作者在该答疑中把盘整结束的标志说成第三类买卖点。',['盘整','第三类买卖点','完成'],[('p0100-b014','盘整结束的标志就是第三类买卖点')],1,'保存盘整的结束标志',conditions=['所讨论相应级别的盘整'])
add(71,'trend-end-divergence-retrace','相应级别趋势结束的标志是该级别背驰后回拉最后一个中枢；回拉必形成更大级别中枢，从而破坏原级别趋势。',['趋势','背驰','走势中枢','中枢扩展','完成'],['p0100-b014','p0101-b000'],1,'保存趋势完成的因果链与级别',conditions=['相应级别趋势','该级别背驰后回拉最后一个中枢'],note='原文跨页续段，不删去“该级别”或改成任意指标回抽。')
add(71,'second-point-no-divergence-needed','可以等趋势回拉后再次反向离开形成第二类买卖点再操作；这种方法可不用背驰概念，只用三类买卖点。',['第二类买卖点','背驰','操作策略'],['p0101-b001'],2,'保存形态操作的替代入口',conditions=['作者所讨论趋势回拉后的再一次向上情境'],note='原文说“再一次向上”，未自行补所有对称分支算法。')
add(71,'first-point-divergence-use','实际操作也可利用背驰在第一类买卖点行动，依据是作者所称“背驰后一定回拉”的定理。',['第一类买卖点','背驰','操作策略'],['p0101-b002'],2,'保存动力学提前行动的依据',conditions=['相应级别背驰成立'],note='未将辅助MACD变化等同背驰成立。')
add(71,'geometry-dynamics-distinction','作者说明即使没有背驰必回拉定理，其理论仍可依走势必完美及第一类点后的第二类点成立；前者关于图形，背驰属于动力学。',['走势终完美','形态学','动力学','背驰','第二类买卖点'],['p0101-b003'],2,'保存形态与动力学论证身份',note='与已复核72课形态学不含背驰相互对照；不据此说纯形态学能识别第一类点。')
add(71,'stroke-vs-segment-no-implication','笔破坏与线段破坏不是互相包含的概念：笔破坏不必然线段破坏，线段破坏也不必然要笔破坏。第一种线段破坏必有笔破坏；第二种未必；线段破坏而无笔破坏则必属第二种。',['笔破坏','线段破坏','特征序列缺口'],['p0101-b008','p0102-b007'],1,'保存双向不蕴涵及两种情况的完整限定',note='已与67课精确定义及72课明确精确化说明对照，不用旧“必被笔破坏”覆盖新定义。')
add(71,'second-case-no-fill-special','作者把第二种线段破坏中连最后特征序列缺口也不回补的情况称为最特殊的一类，并用“所谓小级别转大级别后”描述；线段层次本身不再需要该概念。',['线段破坏','特征序列缺口','小级别转大级别'],['p0101-b009','p0102-b001'],3,'保留旧类比措辞及同课明确适用边界',conditions=['第二种线段破坏','最后特征序列缺口未回补'],note='不把“所谓”旧称恢复为线段定义前提；72课进一步明确特征序列后无需沿用。')
add(71,'novice-larger-level','作者建议新手先练持股，增大操作级别，在大级别买点买入持有到卖点，至少应在30分钟以上；初学者可参考5日线，资金大者参考5周线。',['操作熟练程度','操作级别','持股','均线'],['p0101-b012'],2,'保存面向新手与资金规模的建议',conditions=['新手学习阶段','参考均线而非替代所有级别精确定义'],note='原文“30分钟以上”不改成严格大于30分钟。')
add(71,'trend-vs-center-difference','在自己的操作级别上，中枢震荡短差是高难度活动；趋势中作者要求等待背驰，称该操作级别没有做差价可能。',['中枢震荡','趋势','背驰','操作级别','操作熟练程度'],['p0101-b013'],2,'保存两类状态下策略及操作级别限定',conditions=['一切判断都在操作者选择的操作级别上'],note='不能抹去操作级别后解释为任何更小级别都禁止短差。')
add(71,'stroke-destruction-dynamics','作者说明单独讨论笔破坏是因为它有动力学意义，与背驰同属动力学部分；教学顺序为先形态学、再动力学。',['笔破坏','动力学','形态学','背驰'],[('p0102-b007','笔破坏有动力学上意义。本ID的理论，有一部分和物理学有点类似，就是探讨动力学方面的东西，这方面，各位现在接触最多的就是背驰，而笔破坏，和这一样属于动力学方面的内容，这在以后会逐步说到的。先形态学，再动力学，各位慢慢来。')],2,'保留笔破坏的用途而非强制几何前提')

